mapper.select:
SELECT kl.id, kl.tenant_id AS tenantId, kl.user_id AS userId, kl.question, kl.answer, kl.top_k AS topK, kl.min_score AS minScore, kl.duration_ms AS durationMs, kl.error_message AS errorMessage, kl.status, kl.created_at AS createdAt, COALESCE(kr.reference_count, 0) AS referenceCount FROM knowledge_query_log kl LEFT JOIN ( SELECT query_log_id, COUNT(*) AS reference_count FROM knowledge_query_reference GROUP BY query_log_id ) kr ON kl.id = kr.query_log_id WHERE kl.tenant_id = #{tenantId}
AND kl.status = #{status}
AND kl.answer LIKE CONCAT('%', #{answer}, '%')
ORDER BY kl.created_at DESC
